from collect import make_counter

def test_counter_increments():
    c = make_counter()
    assert [c(), c(), c()] == [1, 2, 3]

def test_counters_isolated():
    a, b = make_counter(), make_counter()
    a()
    assert b() == 1


from recursion import sum_nested

def test_sum_empty_list():
    assert sum_nested([]) == 0

def test_sum_nested_empty_inner():
    assert sum_nested([[], []] ) == 0

def test_sum_plain_number():
    assert sum_nested(5) == 5

def test_sum_mixed():
    assert sum_nested([1, [2], 3]) == 6
